-- Initial source registry. Sources with restrictive or unclear licensing are discovery-only.
on conflict (slug) do update set name=excluded.name, publisher=excluded.publisher, source_type=excluded.source_type, source_url=excluded.source_url, feed_url=excluded.feed_url, api_url=excluded.api_url, documentation_url=excluded.documentation_url, authority_rank=excluded.authority_rank, is_official=excluded.is_official, license_status=excluded.license_status, commercial_use_allowed=excluded.commercial_use_allowed, content_scope=excluded.content_scope, poll_interval_minutes=excluded.poll_interval_minutes, metadata=excluded.metadata, updated_at=now();
